import { useState } from "react";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { Card } from "@/shared/ui/data/Card";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row as LayoutRow } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored verbatim from `@/app/console/lib/idleReaper` (pure, no app-internal deps).
const DEFAULT_STUDIO_IDLE_MS = 30 * 60 * 1000;
function studioIdleMs(cfg) {
  return cfg.studioIdleMs ?? DEFAULT_STUDIO_IDLE_MS;
}
const DEFAULT_REAPER_CONFIG = {
  enabled: true,
  idleMs: 30 * 60 * 1000,
  workerIdleMs: null,
  studioIdleMs: DEFAULT_STUDIO_IDLE_MS,
};

// Vendored from `../pages/SettingsControls` (unresolvable in this sandbox) — unchanged.
function Row({ label, hint, children }) {
  return (
    <LayoutRow gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={13} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{label}</Text>
        {hint && <Text as="div" size={11} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 2 }}>{hint}</Text>}
      </Box>
      {children}
    </LayoutRow>
  );
}
function Select({ value, options, onChange }) {
  return (
    // eslint-disable-next-line no-restricted-syntax -- compact mono <select> for settings rows; not a .field stack
    <select
      value={value}
      onChange={(e) => { const raw = e.target.value; onChange(typeof value === "number" ? Number(raw) : raw); }}
      className="mono"
      style={{ fontSize: 11.5, background: "var(--bg-elev)", color: "var(--fg)", border: "1px solid var(--border)", borderRadius: 6, padding: "5px 8px", cursor: "pointer" }}
    >
      {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

// Preview-only stand-in for `useAppStore().idleReaper` / `setIdleReaperConfig` (app-internal).
export function IdleReaperCard() {
  const [idleReaper, setIdleReaper] = useState(DEFAULT_REAPER_CONFIG);
  const setIdleReaperConfig = (patch) => setIdleReaper((c) => ({ ...c, ...patch }));
  const MIN = 60_000;

  return (
    <Card title="Reap idle background sessions">
      <Stack gap={0}>
        <Row
          label="Enable idle reaper"
          hint="Kill the PTY of an idle, non-visible project/planner session after the timeout to free memory. It shows a dormant placeholder and resumes (where it left off) on click — never destructive."
        >
          <Toggle on={idleReaper.enabled} onClick={() => setIdleReaperConfig({ enabled: !idleReaper.enabled })} />
        </Row>
        <Row
          label="Idle timeout"
          hint="How long a project/planner session sits idle (and unwatched) before it's reaped."
        >
          <Select
            value={idleReaper.idleMs}
            options={[
              { label: "15 min", value: 15 * MIN },
              { label: "30 min (default)", value: 30 * MIN },
              { label: "1 hour", value: 60 * MIN },
              { label: "2 hours", value: 120 * MIN },
            ]}
            onChange={(v) => setIdleReaperConfig({ idleMs: v })}
          />
        </Row>
        <Row
          label="Studio session timeout"
          hint="A studio session (designer, librarian, architect) outlives the page that opened it so its Glance node can still morph into its terminal. This is how long it may sit with nothing showing it before being reclaimed. A session that's still working is never cut off — the reclaim waits until it goes quiet."
        >
          <Select
            value={studioIdleMs(idleReaper)}
            options={[
              { label: "5 min", value: 5 * MIN },
              { label: "15 min", value: 15 * MIN },
              { label: "30 min (default)", value: 30 * MIN },
              { label: "1 hour", value: 60 * MIN },
              { label: "2 hours", value: 120 * MIN },
            ]}
            onChange={(v) => setIdleReaperConfig({ studioIdleMs: v })}
          />
        </Row>
        <Row
          label="Also reap idle workers"
          hint="Off by default — fleet workers idle legitimately (parked on a dependency or the director). When on, a worker is reaped only after a much longer idle (2×)."
        >
          <Toggle
            on={idleReaper.workerIdleMs !== null}
            onClick={() => setIdleReaperConfig({ workerIdleMs: idleReaper.workerIdleMs === null ? idleReaper.idleMs * 2 : null })}
          />
        </Row>
      </Stack>
    </Card>
  );
}
